INSERT OR IGNORE INTO catalog_cards(id,data,status) VALUES ('30','{"id":"30","name":"雷霆薩滿法師","slug":"thunder-shaman","mana":5,"attack":4,"health":7,"subtitle":"雷霆喚靈者","abilities":[{"title":"登場｜雷霆震擊","text":"對一名敵方怪獸造成 3 點傷害。"},{"title":"被動｜祖靈祝福","text":"你的回合結束時，使一名友方怪獸恢復 1 點血量。"}],"image":"cards-clean-layout-31/30-thunder-shaman.webp","collection":"荒野之盟","rulesText":"登場｜雷霆震擊\n對一名敵方怪獸造成 3 點傷害。\n\n被動｜祖靈祝福\n你的回合結束時，使一名友方怪獸恢復 1 點血量。","nameLayout":{"centerX":50,"centerY":54.297,"width":76,"height":5.599,"fontSize":6},"rulesLayout":{"top":60.221,"height":25.065,"notchStart":53.25,"sideInset":24},"translations":{"zh-TW":{"name":"雷霆薩滿法師","subtitle":"雷霆喚靈者","abilities":[{"title":"登場｜雷霆震擊","text":"對一名敵方怪獸造成 3 點傷害。"},{"title":"被動｜祖靈祝福","text":"你的回合結束時，使一名友方怪獸恢復 1 點血量。"}]},"en":{"name":"Thunder Shaman","subtitle":"Stormcaller","abilities":[{"title":"On Play | Thunderstrike","text":"Deal 3 damage to an enemy."},{"title":"Passive | Ancestral Gift","text":"At the end of your turn, restore 1 Health to an ally."}]},"ja":{"name":"雷のシャーマン","subtitle":"雷霊の呼び手","abilities":[{"title":"登場｜雷撃","text":"敵1体に3ダメージを与える。"},{"title":"常時｜祖霊の祝福","text":"自分のターン終了時、味方1体の体力を1回復する。"}]},"ko":{"name":"천둥 주술사","subtitle":"천둥 정령 소환사","abilities":[{"title":"등장 | 천둥 강타","text":"적 하나에게 피해를 3 줍니다."},{"title":"지속 | 선조의 축복","text":"내 턴 종료 시 아군 하나의 생명력을 1 회복합니다."}]}}}','active');
